Craft.EvolutionAPI=(()=>{
 const controller=new AbortController();
 const cancelled=()=>{const error=Error('새 게임을 시작해 이전 진화 확인을 종료했어.');error.cancelled=true;return error;};
 const check=()=>{if(controller.signal.aborted)throw controller.signal.reason;};
 function cancel(){if(!controller.signal.aborted)controller.abort(cancelled());}
 const pause=ms=>new Promise((resolve,reject)=>{check();let timer;const abort=()=>{clearTimeout(timer);reject(controller.signal.reason);},finish=()=>{controller.signal.removeEventListener('abort',abort);resolve();};controller.signal.addEventListener('abort',abort,{once:true});timer=setTimeout(finish,ms);});
 async function request(url,body){check();try{const response=await fetch(url,{...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{}),signal:AbortSignal.any([controller.signal,AbortSignal.timeout(20000)])}),data=await (Craft.Http?Craft.Http.json(response):response.json());check();if(!response.ok){const error=Error(data.error||'진화를 준비하지 못했어요.');error.status=response.status;error.resumable=response.status>=500;throw error;}return data;}catch(error){check();if(['TimeoutError','TypeError'].includes(error.name)){const retry=Error('진행 조회 연결이 늦어지고 있어. 같은 진화 작업을 다시 확인할 수 있어.');retry.resumable=true;throw retry;}throw error;}}
 async function wait(id,onProgress=()=>{}){check();if(!/^[a-f0-9]{32}$/.test(id||''))throw Error('진화 작업 형식 오류');const deadline=Date.now()+1800000;while(Date.now()<deadline){check();let job;for(let attempt=0;attempt<3;attempt++){try{job=await request('/api/evolution/jobs/'+id);break;}catch(error){if(!error.resumable||attempt===2)throw error;onProgress('진행 조회에 다시 연결하고 있어 · 같은 진화를 계속 준비 중');await pause(1600);}}if(job.status==='done')return job.data;if(job.status==='failed')throw Error(job.error||'진화를 완성하지 못했어요.');if(job.status==='cancelled'){const error=Error(job.message||'새 게임으로 이전 진화를 종료했어.');error.cancelled=true;throw error;}check();onProgress(job.message);await pause(1600);}const error=Error('진화 준비가 오래 걸리고 있어. 같은 작업을 다시 확인할 수 있어.');error.resumable=true;throw error;}
 async function artwork(src){check();if(!/^assets\/evolutions\/[a-f0-9]{64}-[01]\.png$/.test(src||''))throw Error('진화 이미지 형식 오류');const image=new Image();image.src=src;await image.decode();check();if(image.naturalWidth!==128||image.naturalHeight!==128)throw Error('진화 이미지 크기 형식 오류');const canvas=document.createElement('canvas');canvas.width=canvas.height=128;canvas.getContext('2d').drawImage(image,0,0);return canvas.toDataURL('image/png');}
 return{cancel,prepare:input=>request('/api/evolution',input),choose:(id,index)=>request('/api/evolution/jobs/'+id+'/choose',{index}),wait,artwork};
})();
